// логи — вне DOCUMENT_ROOT
$outside = dirname($docRoot).'/logs/awz.bxorm';
if(!is_dir($outside)){ @mkdir($outside, 0750, true); }
if(is_dir($outside)){
    $relative = $outside; // абсолютный путь вне web-доступа
}else{
    // fallback: только закрытые каталоги + защита от прямого доступа
    $relative = is_dir($docRoot.'/local/logs') ? 'local/logs' : 'bitrix/php_interface';
    $ht = $docRoot.'/'.$relative.'/.htaccess';
    if(!file_exists($ht)){ @file_put_contents($ht, "Require all denied\n"); }
}

